// IA FALSA, so para o teste local da revisao (15/11/2026). Nao contacta ninguem.
// Geracao: devolve os textos reais do teste de 15/11 (teste-real/resultado.json), com as falhas que tinham.
// Acentos: devolve os textos iguais. Revisao: devolve cada frase com uma correcao mecanica,
// para se ver que a troca entra no sitio certo.
const fs = require('fs');
const path = require('path');
const saida = path.join(__dirname, '..', '..', '..', '..', 'saida');
const real = require(path.join(__dirname, '..', '..', '..', '..', '..', '..', 'proposta-reels-2026-11-15', 'teste-real', 'resultado.json'));
let n = 0;
const corrigir = (f) => f.replace(/[Tt]alvez /g, '').replace(/algo errado/g, 'um erro').replace(/és obrigada a/g, 'tens de')
  .replace(/Em sessão, ouço isto quase todas as semanas/g, 'Em sessão, ouço esta frase');
class Anthropic {
  constructor() {
    this.messages = {
      create: async (params) => {
        n += 1;
        const ferramenta = params.tools[0].name;
        const pedido = params.messages[0].content;
        fs.writeFileSync(path.join(saida, `${String(n).padStart(2, '0')}-${process.env.CENARIO || 'teste'}-${ferramenta}.txt`),
          `=== SYSTEM ===\n${params.system}\n\n=== PEDIDO ===\n${pedido}\n`);
        let input;
        if (ferramenta === 'devolver_textos') input = { textos: JSON.parse(pedido) };
        else if (ferramenta === 'devolver_frases') input = { frases: JSON.parse(pedido).map(x => corrigir(x.frase)) };
        else if (ferramenta === 'entregar_ganchos') input = /Receita R3/.test(params.system) ? real.aberturasR3 : real.aberturas;
        else if (ferramenta === 'entregar_roteiro') input = /sessao/.test(pedido) ? real.roteiroR3 : real.roteiro;
        else throw new Error('IA falsa: ferramenta sem resposta ' + ferramenta);
        return { content: [{ type: 'tool_use', name: ferramenta, input: JSON.parse(JSON.stringify(input)) }] };
      },
    };
  }
}
module.exports = Anthropic;
module.exports.default = Anthropic;
